head.script:
scwin.lastTopRowIndex = -1;
scwin.scrollTimer = null;

scwin.onpageload = function () {
    setTimeout(scwin.printBackground, 300);
};

// 세로 스크롤 시 첫 표시 Row 가 바뀌면 배경색 출력
scwin.grd_A_onscrolly = function (e) {
    clearTimeout(scwin.scrollTimer);
    scwin.scrollTimer = setTimeout(function () {
        if (grd_A.getTopRowIndex() !== scwin.lastTopRowIndex) {
            scwin.printBackground();
        }
    }, 300);
};

// 화면에 표시된 Row 의 지점 / 상품 Cell 배경색 출력
scwin.printBackground = function () {
    let topRowIndex = grd_A.getTopRowIndex();
    let dataLength = grd_A.getDataLength();
    let tbody = document.getElementById(grd_A.id + "_body_tbody");
    if (!tbody) {
        return;
    }
    let trList = Array.prototype.filter.call(tbody.children, function (tr) {
        return tr.tagName === "TR" && tr.style.display !== "none" && tr.querySelector("td[data-col_id]");
    });
    scwin.lastTopRowIndex = topRowIndex;
    scwin.setReturnValue("첫 표시 Row " + topRowIndex);
    for (let i = 0; i < trList.length; i++) {
        let rowIndex = topRowIndex + i;
        if (rowIndex >= dataLength) {
            break;
        }
        let tdBranch = trList[i].querySelector("td[data-col_id='branch']");
        let tdProduct = trList[i].querySelector("td[data-col_id='product']");
        let branchText = tdBranch.textContent.trim();
        let branchLabel = (branchText === "") ? "(숨김)" : branchText;
        scwin.setReturnValue("  Row " + rowIndex + " 지점 " + branchLabel + " " + window.getComputedStyle(tdBranch).backgroundColor
            + "  /  상품 " + window.getComputedStyle(tdProduct).backgroundColor);
    }
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
